package com.kampotourism.itinerary;
import com.fasterxml.jackson.databind.JsonNode; import jakarta.persistence.*; import org.hibernate.annotations.JdbcTypeCode; import org.hibernate.type.SqlTypes;
@Entity @Table(name="itinerary_translation") public class ItineraryTranslation { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(nullable=false) private Long itineraryId; @Column(nullable=false) private String lang; @Column(nullable=false) private String title; @JdbcTypeCode(SqlTypes.JSON) @Column(nullable=false) private JsonNode description; private String seoTitle; private String seoDescription; protected ItineraryTranslation(){} ItineraryTranslation(Long id,String lang){itineraryId=id;this.lang=lang;} void edit(String title,JsonNode description,String seoTitle,String seoDescription){this.title=title;this.description=description;this.seoTitle=seoTitle;this.seoDescription=seoDescription;} public Long getItineraryId(){return itineraryId;} public String getLang(){return lang;} public String getTitle(){return title;} public JsonNode getDescription(){return description;} public String getSeoTitle(){return seoTitle;} public String getSeoDescription(){return seoDescription;} }
